const $ = (s) => document.querySelector(s),
  $$ = (s) => [...document.querySelectorAll(s)];
let me = null,
  csrfToken = null;
const content = $("#content"),
  modal = $("#modal");
async function api(url, opts = {}) {
  const method = (opts.method || "GET").toUpperCase();
  const headers = {
    "Content-Type": "application/json",
    ...(opts.headers || {}),
  };
  if (["POST", "PUT", "PATCH", "DELETE"].includes(method) && csrfToken)
    headers["X-CSRF-Token"] = csrfToken;
  const r = await fetch("/api" + url, { ...opts, headers });
  if (r.status === 204) return null;
  const d = await r.json();
  if (!r.ok) throw Error(d.error || "Request failed");
  return d;
}
function toast(t) {
  const e = $("#toast");
  e.textContent = t;
  e.classList.add("show");
  setTimeout(() => e.classList.remove("show"), 2800);
}
function esc(s = "") {
  return String(s).replace(
    /[&<>"']/g,
    (c) =>
      ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[
        c
      ],
  );
}
function empty(title, desc = "Try a different search or come back later.") {
  return `<div class="empty"><strong>${title}</strong>${desc}</div>`;
}
function heading(title, desc, action = "") {
  return `<div class="section-head"><div><h1 class="page-title">${title}</h1><p>${desc}</p></div>${action}</div>`;
}
const alumniDisplayName = name => String(name||'').replace(/^Fictional Demo \d+ · /,'');
function alumniContactPanel(u,data){
  const rows=[];if(u.email)rows.push('<a href="mailto:'+esc(u.email)+'"><span>Email</span><strong>'+esc(u.email)+'</strong></a>');
  for(const [url,label] of [[u.linkedin_url,'LinkedIn'],[u.website_url,'Website'],[u.github_url,'GitHub'],[u.portfolio_url,'Portfolio']])if(url&&/^https:\/\//i.test(url))rows.push('<a href="'+esc(url)+'" target="_blank" rel="noopener noreferrer"><span>'+label+'</span><strong>Open profile ↗</strong></a>');
  const privateNote=u.source_type==='fictional_demo'?'Sample profiles do not have real contact details.':u.email_visibility?'Contact options shared by this alum are listed here.':'Email is private unless this alum chooses to share it in profile settings.';
  return '<section class="panel profile-contact"><div><span class="eyebrow">CONTACT</span><h2>Get in touch</h2><p>'+privateNote+'</p></div><div class="contact-options">'+(rows.join('')||'<span class="contact-unavailable">No direct contact details shared yet.</span>')+'</div><div class="card-actions">'+(u.source_type!=='fictional_demo'&&me?.id!==u.id?'<button class="button button-outline" data-connect="'+esc(u.id)+'">Connect to request contact</button>':'')+(data.can_message?'<button class="button" data-profile-message="'+esc(u.id)+'">Message this alum</button>':'')+'</div></section>';
}
const demoPortrait = id => {
  const n=Math.abs(Number(id)||1),hue=(n*47)%360,shirt=(n*71)%360,skin=['#c98562','#a9694e','#dfaa83','#8e573f','#d29470'][n%5],hair=['#24232a','#3b2b27','#49352e','#1d2226','#594032','#24212a','#35403c'][n%7];
  const svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 160"><rect width="160" height="160" fill="hsl(${hue} 34% 88%)"/><path d="M20 160c4-36 25-54 60-54s56 18 60 54" fill="hsl(${shirt} 38% 40%)"/><ellipse cx="80" cy="68" rx="35" ry="42" fill="${skin}"/><path d="M45 66c-4-34 13-51 36-51 25 0 39 19 34 50-8-7-13-17-14-27-17 14-34 19-56 18z" fill="${hair}"/><circle cx="67" cy="69" r="2.5" fill="#272226"/><circle cx="94" cy="69" r="2.5" fill="#272226"/><path d="M70 87q10 7 20 0" fill="none" stroke="#854f45" stroke-width="3" stroke-linecap="round"/><path d="M56 108q24 20 48 0" fill="none" stroke="#e5b29a" stroke-width="4"/></svg>`;
  return 'data:image/svg+xml;charset=UTF-8,'+encodeURIComponent(svg);
};
function cardPerson(u, btn = true) {
  const photo=u.profile_photo_url?'<img class="person-photo" src="'+esc(u.profile_photo_url)+'" alt="" loading="lazy">':u.source_type==='fictional_demo'?'<img class="person-photo" src="'+demoPortrait(u.id)+'" alt="Illustrative portrait for fictional demo profile" loading="lazy">':'<span class="person-photo avatar-fallback" aria-hidden="true">'+esc((u.name||'A').split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').slice(0,2).toUpperCase())+'</span>';
  const demo=u.source_type==='fictional_demo';
  return '<article class="card alumni-card"><a class="alumni-person" href="#alumni/'+encodeURIComponent(u.id)+'">'+photo+'<div><h3>'+esc(alumniDisplayName(u.name))+'</h3><p>'+esc(u.job_title||'Alumni member')+(u.company?' · '+esc(u.company):'')+'</p></div></a><div class="tags">'+(u.university_name?(u.university_id?'<a class="tag university-link" href="#university/'+encodeURIComponent(u.university_id)+'">'+esc(u.university_name)+'</a>':'<span class="tag">'+esc(u.university_name)+'</span>'):'')+'<span class="tag">'+esc(u.department||'Department not set')+'</span>'+(u.degree?'<span class="tag">'+esc(u.degree)+'</span>':'')+(u.graduation_year?'<span class="tag">Class of '+esc(u.graduation_year)+'</span>':'')+(demo?'<span class="tag demo-tag">Sample profile</span>':u.verification_status==='verified'?'<span class="tag verified">✓ Verified</span>':'')+'</div><p class="alumni-bio">'+esc(u.bio||'Profile details coming soon.')+'</p><div class="card-actions"><a class="button button-outline button-small" href="#alumni/'+encodeURIComponent(u.id)+'">View Profile</a>'+(btn&&u.role==='alumni'&&!demo?'<button class="button button-outline button-small" data-connect="'+esc(u.id)+'">Connect</button>':'')+'</div></article>';
}
function openModal(html) {
  $("#modalBody").innerHTML = html;
  modal.showModal();
}
function formModal(title, fields, submit, submitText = "Save") {
  openModal(
    `<h2 class="page-title">${title}</h2><form id="modalForm" class="form-grid">${fields}<div class="field full"><button class="button">${submitText}</button></div></form>`,
  );
  $("#modalForm").onsubmit = async (e) => {
    e.preventDefault();
    const data = Object.fromEntries(new FormData(e.target));
    try {
      await submit(data);
      modal.close();
      toast("Saved successfully");
      render();
    } catch (err) {
      toast(err.message);
    }
  };
}
function field(label, name, type = "text", required = false, placeholder = "") {
  return `<div class="field"><label for="${name}">${label}</label><input class="input" id="${name}" name="${name}" type="${type}" ${required ? "required" : ""} placeholder="${placeholder}"></div>`;
}
async function refreshMe() {
  try {
    const current = await api("/auth/me");
    me = current.user;
    csrfToken = current.csrfToken;
  } catch {
    me = null;
    csrfToken = null;
  }
  document.body.classList.toggle("is-admin", me?.role === "admin");
  $("#authBtn").classList.toggle("hidden", !!me);
  $("#joinBtn").classList.toggle("hidden", !!me);
  $("#logout").classList.toggle("hidden", !me);
  $("#avatar").classList.toggle("hidden", !me);
  $("#avatar").textContent = me?.name?.[0] || "A";
  $("#greeting").textContent = me
    ? `Welcome back, ${me.name.split(" ")[0]}.`
    : "A community that moves forward together.";
}
function welcomePage(mode = "login") {
  const registering = mode === "register";
  const fields = (registering ? '<div class="field"><label for="welcomeName">Full name</label><input class="input" id="welcomeName" name="name" autocomplete="name" placeholder="Your name" required></div>' : "") + '<div class="field"><label for="welcomeEmail">University email</label><input class="input" id="welcomeEmail" name="email" type="email" autocomplete="email" placeholder="you@example.com" required></div><div class="field"><label for="welcomePassword">Password</label><div class="password-control"><input class="input" id="welcomePassword" name="password" type="password" minlength="8" autocomplete="' + (registering ? "new-password" : "current-password") + '" placeholder="' + (registering ? "At least 8 characters" : "Enter your password") + '" required><button class="password-toggle" id="welcomePasswordToggle" type="button">Show</button></div></div>';
  const role = registering ? '<div class="field"><label for="welcomeRole">I am joining as</label><select class="input" id="welcomeRole" name="role"><option value="student">Student</option><option value="alumni">Alumni (requires verification)</option></select></div>' : '<div class="auth-meta"><span>Secure sign in</span><span>●</span><span>Your community awaits</span></div>';
  content.innerHTML = '<main class="welcome-screen"><section class="welcome-photo" aria-label="Alumni reconnecting on a university campus"><a class="welcome-brand" href="#home"><img src="/assets/alumniconnect-logo-light.svg" alt="AlumniConnect"></a><div class="photo-shade"></div><div class="welcome-story"><h1>Your University.<br>Your People.<br>Your Next Chapter.</h1><p>Reconnect with your alumni community, discover new opportunities, and build relationships that move your future forward.</p><div class="welcome-caption">Connect <span aria-hidden="true">•</span> Grow <span aria-hidden="true">•</span> Give Back</div></div><span class="photo-credit">ALUMNICONNECT · YOUR LIFELONG NETWORK</span></section><section class="welcome-panel"><div class="welcome-mobile-brand"><img src="/assets/alumniconnect-logo.svg" alt="AlumniConnect"></div><div class="auth-card"><span class="auth-eyebrow">' + (registering ? "BECOME PART OF THE COMMUNITY" : "WELCOME TO ALUMNICONNECT") + '</span><h2>' + (registering ? "Join your network" : "Welcome back") + '</h2><p class="auth-intro">' + (registering ? "Create an account to connect with your university community." : "Sign in to reconnect, find opportunities, and keep in touch.") + '</p><form id="welcomeAuthForm" class="welcome-form">' + fields + role + '<button class="button welcome-submit" type="submit">' + (registering ? "Create my account" : "Sign in to your account") + '<span aria-hidden="true">→</span></button></form><div class="auth-switch">' + (registering ? "Already have an account?" : "New to the network?") + ' <button id="welcomeSwap" type="button">' + (registering ? "Sign in" : "Create an account") + '</button></div><div class="welcome-demo"><span aria-hidden="true">✦</span><span>Local demo · Sample profiles are fictional</span></div></div><p class="welcome-footer">© AlumniConnect <span>·</span> Your Past Connects to Your Future</p></section></main>';
  $("#welcomeSwap").onclick = () => welcomePage(registering ? "login" : "register");
  $("#welcomePasswordToggle").onclick = () => { const input = $("#welcomePassword"); input.type = input.type === "password" ? "text" : "password"; $("#welcomePasswordToggle").textContent = input.type === "password" ? "Show" : "Hide"; };
  $("#welcomeAuthForm").onsubmit = async (e) => { e.preventDefault(); const data = Object.fromEntries(new FormData(e.target)); try { await api("/auth/" + (registering ? "register" : "login"), { method: "POST", body: JSON.stringify(data) }); document.body.classList.remove("guest-mode"); toast(registering ? "Account created" : "Signed in"); await render(); } catch (err) { toast(err.message); } };
}
async function render() {
  await refreshMe();
  const raw=location.hash.slice(1)||"home",parts=raw.split("?"),routePath=parts[0],params=new URLSearchParams(parts[1]||""),view=routePath.split("/")[0];
  if(!me&&routePath!=="home"){
    document.body.classList.add("guest-mode");document.body.classList.remove("home-view");welcomePage();return;
  }
  document.body.classList.remove("guest-mode");
  document.body.classList.toggle("home-view",view==="home");
  const activeView=routePath.startsWith("department/")?"departments":routePath.startsWith("university/")||routePath==="universities"||routePath.startsWith("alumni/")?"alumni-network":view;
  $$("#nav a").forEach(link=>link.classList.toggle("active",link.dataset.view===activeView));
  try{
    if(routePath.startsWith("department/")){await departmentDetail(routePath.slice("department/".length),params);return;}
    if(routePath.startsWith("university/")){await universityDetail(routePath.slice("university/".length));return;}
    if(routePath==="universities"){await universitiesPage(params);return;}
    if(routePath.startsWith("alumni/")){await alumniProfile(routePath.slice("alumni/".length));return;}
    if(routePath.startsWith("messages/")){await messageThread(routePath.slice("messages/".length));return;}
    const f={home,profile,directory,"alumni-network":directory,connections,opportunities,events,mentorship,announcements,departments,messages,community:window.communityHub||community,settings,admin}[view]||home;
    await f(params);
  }catch(error){content.innerHTML=empty("Could not load this page",esc(error.message));}
}
async function alumniProfile(id) {
  const data=await api('/alumni/'+encodeURIComponent(id)+'/details');const u=data.user;const skills=(u.skills||'').split(',').map(x=>x.trim()).filter(Boolean);const photo=u.profile_photo_url?'<img class="profile-photo" src="'+esc(u.profile_photo_url)+'" alt="">':u.source_type==='fictional_demo'?'<img class="profile-photo" src="'+demoPortrait(u.id)+'" alt="Illustrative portrait for fictional demo profile">':'<div class="profile-photo avatar-fallback" aria-hidden="true">'+esc((u.name||'A').split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase())+'</div>';const demo=u.source_type==='fictional_demo';
  const timeline=(rows,kind)=>rows.length?'<div class="timeline">'+rows.map(x=>{if(kind==='education')return '<div class="timeline-item"><span class="timeline-dot"></span><div><h3>'+esc(x.degree||'Education')+' · '+esc(x.field||'Program')+'</h3><strong>'+esc(x.institution)+(x.university_id&&!u.university_name?'':'')+'</strong><div class="subtle">'+esc(x.start_year||'')+(x.start_year&&x.end_year?' – ':'')+esc(x.end_year||'')+'</div>'+(x.description?'<p>'+esc(x.description)+'</p>':'')+'</div></div>';return '<div class="timeline-item"><span class="timeline-dot"></span><div><h3>'+esc(x.title||'Professional experience')+'</h3><strong>'+esc(x.company)+(x.location?' · '+esc(x.location):'')+'</strong><div class="subtle">'+esc(x.start_date||'')+(x.start_date?' – ':'')+esc(x.is_current?'Present':x.end_date||'')+(x.employment_type?' · '+esc(x.employment_type):'')+'</div>'+(x.description?'<p>'+esc(x.description)+'</p>':'')+(x.achievements?'<p>'+esc(x.achievements)+'</p>':'')+'</div></div>';}).join('')+'</div>':'<p class="subtle">No details have been added yet.</p>';
  content.innerHTML='<a class="text-link back-link" href="#alumni-network">← Back to the alumni network</a><section class="panel profile-hero-premium"><div class="profile-cover"></div>'+photo+'<div class="profile-intro"><div class="eyebrow">'+esc(u.university_name||'Alumni community')+' · '+esc(u.department||'Program not listed')+(u.graduation_year?' · Class of '+esc(u.graduation_year):'')+'</div><h1>'+esc(alumniDisplayName(u.name))+'</h1><p class="profile-headline">'+esc(u.headline||u.job_title||'Alumni member')+(u.company?' · '+esc(u.company):'')+'</p><div class="tags">'+(u.degree?'<span class="tag">'+esc(u.degree)+'</span>':'')+(u.industry?'<span class="tag">'+esc(u.industry)+'</span>':'')+(demo?'<span class="tag demo-tag">Sample profile</span>':u.verification_status==='verified'?'<span class="tag verified">✓ Verified alum</span>':'')+'</div><div class="card-actions">'+(demo?'<span class="subtle">Connection requests are disabled for fictional demo profiles.</span>':me?.id!==u.id?'<button class="button" data-connect="'+esc(u.id)+'">Connect</button>'+(data.can_mentor?'<a class="button button-outline" href="#mentorship">Request mentorship</a>':''):'<a class="button" href="#profile">Edit my profile</a>')+'</div></div></section><div class="profile-detail-grid"><section class="panel profile-about"><div class="eyebrow">A LITTLE ABOUT</div><h2>About '+esc(alumniDisplayName(u.name).split(' ')[0])+'</h2><p>'+esc(u.bio||'This alum has not added a biography yet.')+'</p>'+(u.career_interests?'<h3>Career interests</h3><p>'+esc(u.career_interests)+'</p>':'')+(u.mentorship_available?'<h3>Mentorship</h3><p>Open to mentoring · '+esc(u.mentorship_areas||'Areas not listed')+'</p>':'')+'</section><section class="panel"><div class="eyebrow">SKILLS & EXPERTISE</div><h2>What they bring</h2><div class="tags">'+(skills.map(s=>'<span class="tag">'+esc(s)+'</span>').join('')||'<span class="subtle">No skills listed yet.</span>')+'</div>'+(u.achievements?'<h3>Achievements</h3><p>'+esc(u.achievements)+'</p>':'')+(u.research_interests?'<h3>Research interests</h3><p>'+esc(u.research_interests)+'</p>':'')+'</section></div><section class="panel profile-section"><div class="eyebrow">EDUCATION JOURNEY</div><h2>Education</h2>'+timeline(data.education||[],'education')+'</section><section class="panel profile-section"><div class="eyebrow">CAREER TIMELINE</div><h2>Experience</h2>'+timeline(data.experience||[],'experience')+'</section><section class="panel profile-section"><div class="eyebrow">WORK & IDEAS</div><h2>Projects</h2><div class="grid">'+((data.projects||[]).map(p=>'<article class="card"><h3>'+esc(p.title)+'</h3><p>'+esc(p.description)+'</p>'+(p.technologies?'<div class="tags"><span class="tag">'+esc(p.technologies)+'</span></div>':'')+(p.url&&/^https:\/\//i.test(p.url)?'<a class="text-link" href="'+esc(p.url)+'" target="_blank" rel="noopener noreferrer">Project ↗</a>':'')+(p.github_url&&/^https:\/\//i.test(p.github_url)?'<a class="text-link" href="'+esc(p.github_url)+'" target="_blank" rel="noopener noreferrer">GitHub ↗</a>':'')+'</article>').join('')||'<p class="subtle">No projects listed.</p>')+'</div></section><section class="panel profile-section"><div class="eyebrow">CREDENTIALS</div><h2>Certifications</h2><div class="list">'+((data.certifications||[]).map(c=>'<div class="listing"><div><strong>'+esc(c.name)+'</strong><div class="subtle">'+esc(c.issuer)+(c.issued_year?' · '+esc(c.issued_year):'')+'</div></div>'+(c.credential_url&&/^https:\/\//i.test(c.credential_url)?'<a class="text-link" href="'+esc(c.credential_url)+'" target="_blank" rel="noopener noreferrer">Credential ↗</a>':'')+'</div>').join('')||'<p class="subtle">No certifications listed.</p>')+'</div></section>'+(u.linkedin_url||u.github_url||u.website_url||u.portfolio_url?'<section class="panel profile-section profile-links">'+[[u.linkedin_url,'LinkedIn'],[u.github_url,'GitHub'],[u.website_url||u.portfolio_url,'Portfolio']].filter(a=>a[0]&&/^https:\/\//i.test(a[0])).map(a=>'<a class="button button-outline button-small" href="'+esc(a[0])+'" target="_blank" rel="noopener noreferrer">'+a[1]+' ↗</a>').join('')+'</section>':'');
}
