  document.getElementById('search').onclick=()=>load(false);document.getElementById('f-sort').onchange=()=>load(false);document.getElementById('clearFilters').onclick=async()=>{fields.forEach(id=>{const el=document.getElementById('f-'+id);if(el)el.value='';});document.getElementById('f-mentor').checked=false;document.getElementById('f-hiring').checked=false;document.getElementById('f-sort').value='name';await loadDepartments('');document.getElementById('f-department').innerHTML='<option value="">All departments</option>'+departments.map(d=>'<option value="'+esc(d.name)+'">'+esc(d.name)+'</option>').join('');load(false);};document.getElementById('loadMore').onclick=()=>{page++;load(true);};fields.forEach(id=>document.getElementById('f-'+id).onkeydown=e=>{if(e.key==='Enter')load(false);});load(false);loadHighlights();
