async function connections() {
  if (!me) return authPrompt();
  const [a, b, suggestedResult] = await Promise.all([
    api("/connections"),
    api("/connections/requests"),
    api("/alumni?limit=4&sort=recent").catch(() => ({ items: [] })),
  ]);
  const people=(suggestedResult.items||[]).filter(person=>!(a.items||[]).some(connection=>Number(connection.user_id)===Number(person.id))).slice(0,4);
  const accepted=(a.items||[]).map((u)=>cardPerson({ ...u, id: u.user_id }, false)).join("");
  const incoming=(b.items||[]).map((u)=>`<article class="connection-request-card panel"><span class="connection-request-avatar">${esc((alumniDisplayName(u.name)||"A").split(/\s+/).map(part=>part[0]).slice(0,2).join("").toUpperCase())}</span><div class="connection-request-copy"><strong>${esc(alumniDisplayName(u.name))}</strong><small>${esc(u.department||u.role||"Alumni community")} · Requested ${new Date(u.created_at).toLocaleDateString()}</small></div><div class="connection-request-actions"><button class="button button-small" data-respond="${u.id}" data-status="accepted">Accept</button><button class="button button-outline button-small" data-respond="${u.id}" data-status="rejected">Decline</button></div></article>`).join("");
  content.innerHTML =
    heading("Connections", "Build and manage your professional network") +
    `<section class="connections-overview panel"><div class="connections-overview-copy"><span class="eyebrow">YOUR ALUMNI NETWORK</span><h2>Good connections move careers forward.</h2><p>Reconnect with classmates, meet people in your field, and grow a network that shares your university roots.</p><a class="button" href="#directory">Explore alumni <span aria-hidden="true">→</span></a></div><div class="connections-overview-stats"><div><strong>${(a.items||[]).length}</strong><span>Connections</span></div><div><strong>${(b.items||[]).length}</strong><span>New requests</span></div><span class="connections-overview-mark" aria-hidden="true">↗</span></div></section><section class="connection-section"><div class="section-head"><div><span class="eyebrow">YOUR NETWORK</span><h2>Accepted connections</h2><p>${(a.items||[]).length} ${((a.items||[]).length===1)?"person":"people"} in your network</p></div><a class="button button-outline button-small" href="#directory">Find alumni</a></div><div class="connection-grid">${accepted||'<article class="connection-empty panel"><span class="connection-empty-icon" aria-hidden="true">♧</span><div><h3>Your network starts here</h3><p>Find alumni from your university and send a connection request to get started.</p><a class="text-link" href="#directory">Browse the alumni directory →</a></div></article>'}</div></section><section class="connection-section"><div class="section-head"><div><span class="eyebrow">INCOMING</span><h2>Connection requests</h2><p>Review requests from people who want to connect.</p></div><span class="connection-count">${(b.items||[]).length} pending</span></div><div class="connection-request-list">${incoming||'<article class="connection-empty connection-empty-compact panel"><span class="connection-empty-icon" aria-hidden="true">✓</span><div><h3>You’re all caught up</h3><p>New connection requests will appear here.</p></div></article>'}</div></section>${people.length?'<section class="connection-section"><div class="section-head"><div><span class="eyebrow">PEOPLE TO MEET</span><h2>Discover alumni</h2><p>Explore profiles and connect with graduates across the network.</p></div><a class="text-link" href="#directory">View all alumni →</a></div><div class="connection-grid">'+people.map(person=>cardPerson(person,true)).join("")+'</div></section>':''}`;
  $$("[data-respond]").forEach(
    (b) =>
      (b.onclick = async () => {
        await api("/connections/" + b.dataset.respond, {
          method: "PATCH",
          body: JSON.stringify({ status: b.dataset.status }),
        });
        toast("Request updated");
        connections();
      }),
  );
}
