async function authForm(mode) {
  const registering = mode === "register";
  let universityOptions='',departmentOptions='';if(registering){try{const r=await api('/universities');universityOptions=(r.items||[]).map(u=>'<option value="'+esc(u.id)+'">'+esc(alumniDisplayName(u.name))+'</option>').join('')}catch(_){}}
  openModal(
    `<h2 class="page-title">${registering ? "Create your account" : "Welcome back"}</h2><p class="subtle" style="margin:8px 0 20px">${registering ? "Join your university community." : "Sign in to your AlumniConnect account."}</p><form id="authForm">${registering ? `<div class="field"><label for="authName">Name</label><input class="input" id="authName" name="name" autocomplete="name" required></div>` : ""}<div class="field"><label for="authEmail">Email</label><input class="input" id="authEmail" name="email" type="email" autocomplete="email" required></div><div class="field"><label for="authPassword">Password</label><div class="password-control"><input class="input" id="authPassword" name="password" type="password" minlength="8" autocomplete="${registering ? "new-password" : "current-password"}" required><button class="password-toggle" id="togglePassword" type="button" aria-label="Show password">Show</button></div></div>${registering ? `<div class="field"><label for="authRole">Account type</label><select class="input" id="authRole" name="role"><option value="student">Student</option><option value="alumni">Alumni (requires verification)</option></select></div><div class="field"><label for="authUniversity">University (optional)</label><select class="input" id="authUniversity" name="university_id"><option value="">Choose university</option>${universityOptions}</select></div><div class="field"><label for="authDepartment">Department / program</label><select class="input" id="authDepartment" name="department"><option value="">Choose university first</option></select><small class="subtle">Program listings may need university confirmation.</small></div>` : ""}<button class="button" style="width:100%;margin-top:8px">${registering ? "Create account" : "Sign in"}</button></form><p class="subtle" style="margin-top:14px">${registering ? "Already registered?" : "New here?"} <a href="#" id="swapAuth">${registering ? "Sign in" : "Create an account"}</a></p><div class="notice">Local demo credentials are listed in README.md.</div>`,
  );
  if(registering){$("#authUniversity").onchange=async e=>{try{const r=await api('/departments?university_id='+encodeURIComponent(e.target.value));$("#authDepartment").innerHTML='<option value="">Choose department</option>'+r.items.map(d=>'<option value="'+esc(d.name)+'">'+esc(d.name)+(d.confirmation_status==='verified'?'':' · awaiting confirmation')+'</option>').join('')}catch(_){$("#authDepartment").innerHTML='<option value="">Departments unavailable</option>'}}}
  $("#togglePassword").onclick = () => {
    const password = $("#authPassword");
    const show = password.type === "password";
    password.type = show ? "text" : "password";
    $("#togglePassword").textContent = show ? "Hide" : "Show";
    $("#togglePassword").setAttribute(
      "aria-label",
      show ? "Hide password" : "Show password",
    );
  };
  $("#swapAuth").onclick = (e) => {
    e.preventDefault();
    authForm(registering ? "login" : "register");
  };
  $("#authForm").onsubmit = async (e) => {
    e.preventDefault();
    const d = Object.fromEntries(new FormData(e.target));
    try {
      await api("/auth/" + (registering ? "register" : "login"), {
        method: "POST",
        body: JSON.stringify(d),
      });
      modal.close();
      toast(registering ? "Account created" : "Signed in");
      render();
    } catch (x) {
      toast(x.message);
    }
  };
}
