    '<section class="settings-section"><div class="section-head"><div><span class="eyebrow">PROFILE PRIVACY</span><h2>Visibility & contact</h2><p>These preferences apply to your alumni network profile.</p></div></div><form id="settingsForm" class="settings-card panel"><div class="settings-option"><span class="settings-option-icon" aria-hidden="true">◎</span><div class="settings-option-copy"><label for="settingsVisibility">Profile visibility</label><p>Choose who can discover your profile and professional details.</p></div><select class="input" id="settingsVisibility" name="profile_visibility"><option value="public">Alumni network</option><option value="connections">Connections only</option><option value="private">Private</option></select></div><div class="settings-option settings-email-option"><span class="settings-option-icon" aria-hidden="true">✉</span><div class="settings-option-copy"><label for="settingsEmail">Show email address</label><p>Your email is hidden from profiles unless you turn this on.</p></div><label class="settings-switch"><input id="settingsEmail" type="checkbox" name="email_visibility" value="true"><span aria-hidden="true"></span></label></div><div class="settings-card-footer"><span>Your privacy settings can be changed at any time.</span><button class="button" type="submit">Save preferences <span aria-hidden="true">→</span></button></div></form></section>'+
    '<section class="settings-section"><div class="section-head"><div><span class="eyebrow">ACCOUNT SAFETY</span><h2>Blocked accounts</h2><p>People you block cannot contact you or view your profile.</p></div><span class="connection-count">'+blocked.length+' '+(blocked.length===1?"account":"accounts")+'</span></div><div class="blocked-account-list">'+(blockedRows||'<article class="blocked-empty panel"><span class="connection-empty-icon" aria-hidden="true">✓</span><div><h3>No blocked accounts</h3><p>Accounts you block will appear here. You’re all clear for now.</p></div></article>')+'</div></section>';
  $("#settingsVisibility").value=me.profile_visibility||"public";$("#settingsEmail").checked=!!me.email_visibility;
