async function showSearchResults(query,target) {
  const q=query.trim();
  if(q.length<2){target.classList.add('hidden');return;}
  try {
    const [data,uniData]=await Promise.all([api('/search?q='+encodeURIComponent(q)),api('/universities?q='+encodeURIComponent(q)).catch(()=>({items:[]}))]);
    const links=[...(data.alumni||[]).map(x=>['#alumni/'+encodeURIComponent(x.id),x.name+' · '+(x.department||'Alumni')]),...(uniData.items||[]).slice(0,5).map(x=>['#university/'+encodeURIComponent(x.id),x.name+' · University']),...(data.departments||[]).map(x=>['#department/'+encodeURIComponent(x.id),x.name+' · Department']),...(data.jobs||[]).map(x=>['#opportunities',x.title+' · '+x.company]),...(data.events||[]).map(x=>['#events',x.title+' · Event'])];
    target.innerHTML=links.map(x=>'<a href="'+x[0]+'">'+esc(x[1])+'</a>').join('')+'<a class="search-all-link" href="#directory?q='+encodeURIComponent(q)+'">Search alumni directory for “'+esc(q)+'” →</a>';
  } catch(e) { target.innerHTML='<div class="subtle">Search unavailable</div>'; }
  target.classList.remove('hidden');
}
function bindSearch(input,target){
  if(!input||!target)return;let timer;
  input.addEventListener('input',()=>{clearTimeout(timer);const q=input.value.trim();if(q.length<2){target.classList.add('hidden');return;}timer=setTimeout(()=>showSearchResults(q,target),180);});
  input.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();clearTimeout(timer);showSearchResults(input.value,target);}});
  input.form?.addEventListener('submit',e=>{e.preventDefault();clearTimeout(timer);showSearchResults(input.value,target);});
}
const globalInput=$("#globalSearch"),globalResults=$("#globalResults");bindSearch(globalInput,globalResults);
document.addEventListener('click',e=>{if(!e.target.closest('.global-search')&&!e.target.closest('#globalResults')&&!e.target.closest('.home-search')){globalResults?.classList.add('hidden');$('#homeSearchResults')?.classList.add('hidden');}});
